\version "2.27.2"
% automatically converted by musicxml2ly from 24g-GraceNote-Dynamics.xml
\pointAndClickOff

\header {
  texidoc = "Grace notes in combination with dynamics. The ‘f’ sign is located
    on the first grace note (using a <direction> element), followed by a
    diminuendo wedge, and the ‘p’ sign is on the main beat (again using
    <direction>)."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative g'' {
  \clef "treble" \numericTimeSignature \time 4/4 \key c \major \grace { g16 [
    _\f _\> f16 e16 d16 ] } c4 \! _\p }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
